      "announcement_text": "Let us listen for a different sort of magic, friend, as the Rainbooms begin to find their instruments.\n\nYou could have set your watch by the way DJ Pon-3 went to school, provided your watch had a very good bass line. She put on her headphones and the crossing guard’s gestures, the baby birds opening their beaks, even a dog barking fell into time with her music. She stopped for a cupcake at the sweet shop. At school the bell rang and Principal Celestia held out a hand for the headphones. DJ gave them up without arguing. As soon as the principal turned around, out came the spare earbuds. That was the girl who would one day be able to walk through a school full of enchanted people and fetch a sound system. Her precautions that morning had been intended simply to get her as far as class.\n\nRainbow Dash needed a new guitar. At the music shop she got a hand on a double-necked electric at the same instant as Trixie. Applejack proposed settling it with a little playing, which gave these two an excuse to do what they’d wanted from the beginning. Trixie had the chops to make Rainbow work for it. Halfway through trying to outplay her, Rainbow found herself in the air, ears and wings out, with a charge running through the guitar she was actually playing. By the time she landed she knew which instrument she wanted. DJ could hand the double-necked one to Trixie. It was a lovely victory for Trixie right up to the moment she saw what the shop wanted for it. Twelve thousand dollars. Rainbow was already out the door.\n\nFluttershy made an appointment months in advance for something most people would have been happy to let somebody else do. Once a year a volunteer at the rescue center got to give the hamster habitat a proper cleaning. All those tubes needed scrubbing. Rarity came along to look after the occupants. By the time Fluttershy had finished, Rarity had named the hamsters, dressed at least one, and acquired a detailed personal account of who had chewed whose scarf. She had rather less information about how to get everybody back into the habitat.\n\nA tambourine fell out of Fluttershy’s bag. The little heads turned. She shook it again and led her charges back in, sprouting wings and ears of her own along the way. She was beginning to find out what an instrument could do in her own hands. The audience Rarity couldn’t keep in a room would follow Fluttershy anywhere.\n\nFor some time Rainbow went around discussing what sort of person would make a good drummer, frequently in the presence of Pinkie Pie and a noise for which Pinkie Pie was responsible. During preparations for a banner, Rainbow authorized the liberal use of glitter. Pinkie tapped out a rhythm on the container and distributed it quite liberally over Rainbow. At lunch there was an entire percussion section available in the form of cutlery, trays, glasses, and people's heads. Rainbow carried on explaining how much energy a drummer needed. You began to hope, for the sake of everyone trying to finish lunch, that the answer would occur to her soon.\n\nRarity suggested finding somewhere for Pinkie to put all that energy. Behind a drum kit at last, Pinkie played a solo that brought out her pony ears. Rainbow was pleased with herself for having spotted the talent. Pinkie let her have that one and supplied the rimshot.\n\nMy ears perk at the thought of an instrument finding its musician. Fluttershy was not suddenly a different girl when the tambourine worked. She had spent all that time learning to be gentle with small creatures. The music gave something already present in her a way to be heard. Rarity and her grand piano, on the other hoof, might have benefited from a little advance planning.\n\nRarity had a related problem. She could play piano beautifully. The piano was at one end of the school, the others had booked the band room at the other, and the instrument was a grand. She enlisted the Diamond Dog boys to move it and arrived riding on top. She made an entrance the girls would remember. She also made it just in time for the end of their reservation. Practice would have to move to the gym.\n\nPinkie, now in a position to say something about finding the right instrument, offered her a keytar. Rarity tried it. She could play it standing up, wear it on a strap, and make sounds worth growing pony ears for. A discovery of this importance might reasonably have released the moving crew for the afternoon. Rarity accepted the keytar and asked the boys for a ride to the gym on the piano.\n\nApplejack had a perfectly good bass already. Unfortunately, her grandmother had sold it for two dollars at a garage sale. The new owners, Flim and Flam, offered to sell it back to her for a thousand. Rarity remembered what they’d paid. The brothers seemed to feel they’d incurred some very considerable transportation expenses. The instrument even had Applejack’s initials on its strap, and still they doubted it was hers. Then they made the mistake of wondering aloud whether she could play it.\n\nShe picked up that bass and gave them their answer. Her friends helped negotiate the rest. Getting her instrument home involved a shift promoting the shop out on the sidewalk in a banana suit, where Granny Smith had occasion to discover that her granddaughter played the bass. Applejack could have wished for a more convenient moment for her grandmother to take an interest in her music.\n\nAcross the mirror, Princess Twilight missed these girls enough to imagine whole evenings with them. It was easy to picture a school party, although the difficult part was letting six different people decorate. In one such evening Pinkie’s luau came down around her, Rainbow’s sporting equipment flew about at head height, and Applejack’s rodeo bull provided excitement in excess of requirements. Rarity favored a masquerade. Fluttershy would have invited enough animals to populate a petting zoo. Twilight’s own idea looked suspiciously like additional time to study. Rainbow found room for a little of everybody’s idea, and they could finally play “Shake Your Tail!” for a party they all recognized as theirs.\n\nGive Twilight a carnival to picture and she could find things to love about every pair that wandered off together. Applejack and Rainbow took on a test of strength and got upstaged by little Spike. Pinkie and Rarity found the cotton candy. Fluttershy approached Whack-a-Mole with a firm personal conviction that a succession of little heads popping out to see her was an invitation to pet them. There were texts back and forth, then a photo booth where everybody could fit, and finally the Ferris wheel going up into the night. Back in Equestria, Twilight could have told you exactly whom she wanted beside her at the top.",
      "audio_sha256": "69017c751f0ad100a07007307e1a17171e19fa74eca9d522635afa13fb6298f8",
