      "announcement_text": "Now that the instruments are together, there is the considerably more complicated matter of becoming a band.\n\nOnce all five could make it to rehearsal with their instruments, you could tell whose idea the Rainbooms had been by listening to Rainbow say my band within earshot of the four other people required to make it sound good. She played lead guitar and sang. Applejack played bass, Pinkie drums, Rarity keytar, Fluttershy tambourine. Fluttershy wrote songs, too. Getting one past Rainbow and onto the set list was another matter.\n\nSunset hung around their rehearsals. The five had made room for her socially, a kindness she felt keenly in a school where an entire hallway might still go cold at the sight of her. She had yet to find out what she could say in that room. If Rainbow steamrolled Fluttershy, did the former school bully really get to be the one who pointed it out? Sunset often spotted trouble early and let the moment to speak pass. Everybody else had a grievance they were letting pass, too. Rarity put work into costumes that Applejack could have done without. Pinkie could remember when rehearsal had been fun.\n\nThen three new girls arrived. Adagio Dazzle did most of the steering. Aria Blaze had a gift for getting a dig in, and Sonata Dusk could exasperate the other two at conversational walking speed. As the Dazzlings, though, they could sing together beautifully. They wore red pendants at their throats. In Equestria they had been sirens, able to feed on discord. They persuaded a cafeteria full of teenagers that the upcoming musical showcase would be much more interesting if everybody had somebody to beat.\n\nFor help, Sunset turned to a book she’d brought from home. A message written in it could appear in a companion volume in Equestria. Princess Twilight found a way to use the books to reopen the portal, and back she came, to a group of friends enormously relieved to hand the problem to her. Twilight set to work on a musical counterspell. At Pinkie’s sleepover she borrowed Fluttershy’s notebook and found one of the songs Fluttershy had written. Later, when the house was quiet, Sunset found Twilight still at it in the kitchen. It was easier for the princess to admit how stuck she felt with just Sunset there. Pinkie’s sister Maud came through for a snack for her pet rock, Boulder. Even a private conversation about saving the world had to accommodate the habits of the Pie household.\n\nDuring “Awesome as I Wanna Be,” Rainbow had the room. She was enjoying herself so much that her magic began to show. Playing music with her friends could give her pony ears, wings, and a flowing tail. Normally that would have been quite a finish. With the Dazzlings watching for precisely that power, Sunset tackled her to stop the performance. To Rainbow it felt like public humiliation. To Sunset it was one more occasion on which doing something about a problem had made everybody look at her the old way.\n\nThe argument finally happened underneath the stage, where a furious Trixie had trapped the Rainbooms. Above them, the Dazzlings were having a wonderful evening. Below, Fluttershy finally said what it was like to write a song and never get to hear her friends play it. Twilight admitted how much pressure she was under. Sunset told them what she’d seen happening between them and what had kept her quiet. There was time, at last, for the girls to hear the ends of one another’s sentences.\n\nThe silver sigil on my flank glimmers with quiet affection, friend. Fluttershy's song did not become good when Rainbow finally chose it. It was good in the notebook. The difference was that the other girls had learned how to listen. And Sunset, who had once made a great art of controlling people, had something quite different to contribute when she was finally invited up to sing.\n\nThey got out with help from Spike and DJ Pon-3, whose headphones had kept the sirens out of her head and whose sound system could make up for a lot of lost ground. They still had to choose a song. Rainbow picked the one Fluttershy had written. Fluttershy made a little sound of pure delight. Then Applejack turned to Rarity. If they were going to do this, she wanted those stage outfits. By the time Twilight called Sunset up to sing with them during “Welcome to the Show,” each girl had heard something from a friend that she’d been waiting a long time to hear. A girl who’d spent rehearsal wondering whether she had permission to speak had an audience now, and she sang. Together the Rainbooms shattered the sirens’ pendants. Left to sing without magic, the Dazzlings made a rapid exit.\n\nPrincess Twilight went home again. Sunset stayed with the band, singing and playing guitar. She could write to Twilight when she needed her. She also had people close enough to hear her without the help of an enchanted book.\n\nSunset still remembered the photographs of herself in Principal Celestia’s office. There she was, the reigning princess at one Fall Formal after another. A girl passing them on her way to see the principal could have come away with the idea that these had been the happiest nights of Sunset’s life. Sunset could look at the very same pictures and remember how much work she’d put into making other girls afraid to run against her. She took the old pictures down.\n\nI have a particular fondness for the image of Sunset on that roof. A memory need not be denied for the person who carries it to change. Those photographs are evidence of a real past; the song is evidence of a real present. Both belong to her life.\n\nUp on the school roof at dusk, that was some of what she put into “My Past Is Not Today.” She had memories of wings which still had the power to frighten her. This time, as her old leather jacket caught the wind, she could picture wings bright as a phoenix opening behind her. She’d been the girl in the pictures. Here she was, too, making something she could sing in her own voice.\n\nRarity had a favorite place from which to imagine her whole town looking magnificent. It was at the sewing machine, where even the most magnificent idea ultimately came down to getting two pieces of cloth to meet. In “Life Is a Runway” she could see Miss Cheerilee, Lyra Heartstrings, Sweetie Drops and the others walking down the street, each discovering how much fun it could be to have the right outfit at the right moment. In her head she could dress half the neighborhood in the time it took to get through a song. Back at the worktable there was actual clothing to show for the hours she put in.\n\nAnd then there was what happened when everybody got a say in the music. A song could begin at Twilight’s piano, take Sunset out into a field of dandelions with Fluttershy, and let her come up through one of Rarity’s enormous, brilliantly colored flowers. In Rainbow’s hands there was a crowd ready to carry Sunset overhead. Applejack could put her on horseback and get her up to line-dance. Pinkie could give the whole business an electronic beat. By the end of “Friendship Through the Ages,” all those girls were in one another’s arms. If you had asked for the sound of the Rainbooms and expected a single kind of music, you might have needed the whole song to get your answer.",
      "audio_sha256": "8b656da3d4e063187285f1bd54754af9fb5d19fe4301bd249e325c97d14f15c8",
