      "announcement_text": "Sunset has a place among the girls now. I would like to spend a little more time with her as she learns what that place means.\n\nSunset kept a holiday appointment with a book. She could write Princess Twilight about missing home and expect the page to fill with an answer. That mattered on a holiday. Your friends could invite you over and carry on traditions that went back before you knew them, and there would be an entire other world’s worth of things you’d have to stop and explain about your own.\n\nAt a sleepover Applejack let slip an old nickname, Piggly Wiggly. It belonged to the little girl she’d been at home, the one her family remembered. When a MyStable account called Anon-a-Miss posted it for the whole school to see, it was easy to work out who’d been in the room. After another sleepover, photographs from Sunset’s phone appeared on the account. Now it looked easy to work out who’d done it, too. The girls drew the wrong conclusion. For Sunset there was a particular kind of loneliness in discovering that the people who could hurt her most were the ones she’d finally been able to trust.\n\nMy ears droop a little at this part, friend. A confidence shared around a room has a different meaning from the same words broadcast across an entire school. An apology cannot make those words unheard, but it can change how the people who heard them choose to act tomorrow.\n\nThe people behind the account were Apple Bloom, Sweetie Belle, and Scootaloo. The younger girls had been watching their sisters and friends make room for Sunset and feeling themselves edged out. Then other students began submitting secrets of their own. It had grown very big and remarkably ugly by the time the three came forward. They apologized to Sunset. Rarity, to her credit, had an apology of her own for Sweetie Belle. Grown-ups were going to see to the detention. The sisters had to work out how to make room for one another again. The holiday ended at the Apples’, where there was room for Sunset, too.\n\nThere was nothing about a chemistry exam that Sunset found especially trying. Discovering that all her friends had studied for it together without her was another matter. She had people to sit with at lunch now, but the others also had clubs to get to and years of knowing how to fill a school afternoon. Sitting around waiting for them to finish hardly seemed a promising new direction for somebody who’d once had a private tutor with a kingdom to run.\n\nThere is something wonderfully ordinary about Sunset trying to find a school activity. Even a pony from another world can be lonely on an afternoon when all her friends are busy. I am rather glad her solution involved making things with other people, rather than proving to them how exceptional she was.\n\nShe took on a fundraiser for new team uniforms. If you put Rarity in reach of a fashion show, Fluttershy in reach of a pet parade, and friends who could bake in reach of a bake sale, you could get yourself a full program rather quickly. You could also promise six different people more help than one student could deliver. When arrangements started going wrong, Sunset had to go around putting her own mistakes right. She designed a way of showing off the uniforms digitally. Selling tickets took something more personal. She went up to students, listened to them, and even got Trixie to lend her considerable powers of persuasion. Come the evening, Rarity had made her a dress. Sunset got up there with the Rainbooms and heard people in the audience speaking well of her before they knew she could hear.",
      "audio_sha256": "6f48b7fa6f5d9f60107a364c013d7e0d68c33dd83902979f13a520b37bc8a749",
      "audio_url": "audio/6ac2e0a3c3fd9774794858608aff6e28c5abe8dd74fdc44330da709b6cf433ac.mp3",
